    `})},re={name:"No Fields (Content Only)",render:()=>({components:{DocumentViewerShell:ae},setup(){return{docNoFields:Object.assign({},te,{pages:te.pages.map(function(m){return Object.assign({},m,{fields:[]})})}),RECIPIENTS:de}},template:`
      <DocumentViewerShell
